const lessons=[{"sentences":[{"speaker":"A","text":"Good morning and thank you for calling the maple homestay service today.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.488375},{"speaker":"B","text":"Good morning because I want to book a short room stay for next month.","position":2,"audioStartSeconds":4.688375,"audioEndSeconds":8.828416666666667},{"speaker":"A","text":"I can certainly help you with that booking if you tell me your details.","position":3,"audioStartSeconds":9.028416666666667,"audioEndSeconds":13.179833333333333},{"speaker":"B","text":"My family needs a nice bedroom that includes a private bathroom please.","position":4,"audioStartSeconds":13.379833333333334,"audioEndSeconds":18.213083333333334},{"speaker":"A","text":"That specific room costs forty pounds per night during the middle week.","position":5,"audioStartSeconds":18.413083333333333,"audioEndSeconds":23.013583333333333},{"speaker":"B","text":"That price sounds very reasonable although we also need some transport help.","position":6,"audioStartSeconds":23.213583333333332,"audioEndSeconds":28.13625},{"speaker":"A","text":"We provide a free station shuttle when guests arrive by the afternoon train.","position":7,"audioStartSeconds":28.33625,"audioEndSeconds":33.155833333333334},{"speaker":"B","text":"That will work wonderfully because our train reaches the local station at noon.","position":8,"audioStartSeconds":33.35583333333334,"audioEndSeconds":38.098125},{"speaker":"A","text":"Actually our shuttle only runs from two o'clock so noon is too early.","position":9,"audioStartSeconds":38.298125,"audioEndSeconds":42.847125},{"speaker":"B","text":"Oh I see when should we catch a later train to fit your schedule?","position":10,"audioStartSeconds":43.047125,"audioEndSeconds":47.145041666666664},{"speaker":"A","text":"If you catch the afternoon express you will arrive by three o'clock easily.","position":11,"audioStartSeconds":47.34504166666667,"audioEndSeconds":51.894},{"speaker":"B","text":"We will change our train tickets so we arrive at three o'clock instead.","position":12,"audioStartSeconds":52.094,"audioEndSeconds":56.681625},{"speaker":"A","text":"That adjustment solves the transport problem completely for your family.","position":13,"audioStartSeconds":56.881625,"audioEndSeconds":61.41770833333333},{"speaker":"B","text":"Could you send the booking confirmation email to my personal home address?","position":14,"audioStartSeconds":61.61770833333333,"audioEndSeconds":66.11854166666667},{"speaker":"A","text":"I will send that message immediately once you confirm your family name.","position":15,"audioStartSeconds":66.31854166666666,"audioEndSeconds":70.92895833333333}],"questions":[{"prompt":"Required room feature: ______","answer":"private bathroom","evidenceSentence":4,"evidence":"private bathroom","explanation":"Khách hàng yêu cầu một phòng ngủ có phòng tắm riêng."},{"prompt":"Nightly room fee: ______ pounds","answer":"forty","evidenceSentence":5,"evidence":"forty pounds","explanation":"Chi phí cho phòng đó là bốn mươi bảng mỗi đêm."},{"prompt":"Transport service provided: ______ shuttle","answer":"station","evidenceSentence":7,"evidence":"station shuttle","explanation":"Dịch vụ cung cấp xe đưa đón nhà ga miễn phí."},{"prompt":"Initial arrival time: ______","answer":"noon","evidenceSentence":8,"evidence":"noon","explanation":"Ban đầu khách định đến vào lúc trưa (noon)."},{"prompt":"Corrected arrival time: ______ o'clock","answer":"three","evidenceSentence":12,"evidence":"three o'clock","explanation":"Thời gian đổi lại là ba giờ chiều."},{"prompt":"Document to receive: ______ confirmation","answer":"booking","evidenceSentence":14,"evidence":"booking confirmation","explanation":"Khách yêu cầu gửi email xác nhận đặt phòng."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
